// UpdateInput describes one update.
type UpdateInput struct {
	Mode          string
	Body          string // Markdown, or storage for replace_storage
	Find          string
	ReplaceAll    bool
	Section       string
	BodyFormat    string // markdown | storage (for replace_section)
	AllowRemovals bool
}

// UpdateResult is the new storage and what reviewers should know about it.
type UpdateResult struct {
	Storage  string   `json:"-"`
	Warnings []string `json:"warnings,omitempty"`
	Changes  int      `json:"changes"`
}

// ApplyUpdate computes the new storage for an existing document. It never
// converts the existing document to Markdown and back: every mode either adds
// new content beside the original or edits the original in place.
func ApplyUpdate(old string, in UpdateInput) (UpdateResult, error) {
	var res UpdateResult
	switch in.Mode {
	case ModeAppend:
		if strings.TrimSpace(in.Body) == "" {
			return res, errors.New("추가할 본문(body)이 비어 있습니다")
		}
		res.Storage, res.Changes = old+FromMarkdown(in.Body), 1
	case ModePrepend:
		if strings.TrimSpace(in.Body) == "" {
			return res, errors.New("추가할 본문(body)이 비어 있습니다")
		}
		res.Storage, res.Changes = FromMarkdown(in.Body)+old, 1
	case ModeReplaceText:
		if in.Find == "" {
			return res, errors.New("replace_text 에는 find 가 필요합니다")
		}
		out, n := ReplaceText(old, in.Find, in.Body, in.ReplaceAll)
		if n == 0 {
			return res, fmt.Errorf("본문에서 %q 를 찾을 수 없습니다 (매크로·코드 블록 내부는 바꾸지 않습니다)", in.Find)
		}
		res.Storage, res.Changes = out, n
	case ModeReplaceSection:
		start, end, err := Section(old, in.Section)
		if err != nil {
			return res, err
		}
		region := old[start:end]
		body := in.Body
		if in.BodyFormat != "storage" {
			body = FromMarkdown(in.Body)
		}
		if lost := Lost(Take(region), Take(body)); len(lost) > 0 {
			if !in.AllowRemovals {
				return res, fmt.Errorf("%w: 바꾸려는 구역에 보존할 수 없는 요소가 있습니다 (%s). storage 형식으로 보내거나 allowRemovals 로 제거를 명시하십시오",
					ErrUnsupported, strings.Join(lost, ", "))
			}
			res.Warnings = append(res.Warnings, "제거되는 요소: "+strings.Join(lost, ", "))
		}
		res.Storage, res.Changes = old[:start]+body+old[end:], 1
	case ModeReplaceStorage:
		if _, err := Parse(in.Body); err != nil {
			return res, err
		}
		if lost := Lost(Take(old), Take(in.Body)); len(lost) > 0 {
			if !in.AllowRemovals {
				return res, fmt.Errorf("%w: 새 본문에서 기존 요소가 사라집니다 (%s). 의도한 삭제라면 allowRemovals 를 true 로 보내십시오",
					ErrUnsupported, strings.Join(lost, ", "))
			}
			res.Warnings = append(res.Warnings, "제거되는 요소: "+strings.Join(lost, ", "))
// Package tools defines the MCP tool surface over Confluence and the pipeline
// that authorises every call: identity → requester permission → policy →
// approval → idempotent write → verification.
package tools

import (
	"errors"
	"fmt"
	"strings"
)

// Args is a decoded MCP tool argument map.
type Args map[string]any

// String returns a required string argument.
func (a Args) String(name string) (string, error) {
	v, ok := a[name]
	if !ok || v == nil {
		return "", fmt.Errorf("필수 인자 %s 가 없습니다", name)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("인자 %s 는 문자열이어야 합니다", name)
	}
	s = strings.TrimSpace(s)
	if s == "" {
		return "", fmt.Errorf("인자 %s 가 비어 있습니다", name)
	}
	return s, nil
}

// OptString returns an optional string argument.
func (a Args) OptString(name, def string) string {
	if v, ok := a[name]; ok {
		if s, ok := v.(string); ok && strings.TrimSpace(s) != "" {
			return strings.TrimSpace(s)
		}
	}
	return def
}

// Int returns a required integer argument.
func (a Args) Int(name string) (int, error) {
	v, ok := a[name]
	if !ok || v == nil {
		return 0, fmt.Errorf("필수 인자 %s 가 없습니다", name)
	}
	n, ok := toInt(v)
	if !ok {
		return 0, fmt.Errorf("인자 %s 는 정수여야 합니다", name)
	}
	return n, nil
}

// OptInt returns an optional integer argument.
func (a Args) OptInt(name string, def int) int {
	if v, ok := a[name]; ok && v != nil {
		if n, ok := toInt(v); ok {
			return n
		}
	}
	return def
}

// OptBool returns an optional boolean argument.
func (a Args) OptBool(name string, def bool) bool {
	if v, ok := a[name]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return def
}

// StringSlice returns an optional string list argument.
func (a Args) StringSlice(name string) []string {
	v, ok := a[name]
	if !ok || v == nil {
		return nil
	}
	switch t := v.(type) {
	case []string:
		return t
	case []any:
		out := make([]string, 0, len(t))
		for _, item := range t {
			if s, ok := item.(string); ok && strings.TrimSpace(s) != "" {
				out = append(out, strings.TrimSpace(s))
			}
		}
		return out
	case string:
		parts := strings.Split(t, ",")
		out := make([]string, 0, len(parts))
		for _, p := range parts {
			if strings.TrimSpace(p) != "" {
				out = append(out, strings.TrimSpace(p))
			}
		}
		return out
	}
	return nil
}

func toInt(v any) (int, bool) {
	switch t := v.(type) {
	case int:
		return t, true
	case int32:
		return int(t), true
	case int64:
		return int(t), true
	case float64:
		return int(t), true
	case float32:
		return int(t), true
	case string:
		var n int
		if _, err := fmt.Sscanf(strings.TrimSpace(t), "%d", &n); err == nil {
			return n, true
		}
	}
	return 0, false
}

// ErrNotImplemented marks a tool that is registered but intentionally off.
