	}

	if c.Target.ContentID != "" {
		ct, err := c.Adapter.Content(ctx, c.Cred, c.Target.ContentID, "space", "version", "ancestors", "container")
		if err != nil {
			if confluence.IsStatus(err, 403, 404) {
