			res.Ancestors = append(res.Ancestors, ct.Container.ID)
		}
	} else {
		res.SpaceKey = strings.ToUpper(c.Target.SpaceKey)
		if dec.SpaceKey != "" {
			res.SpaceKey = dec.SpaceKey
		}
