		KeycloakUsername: id.User.Username, ToolName: req.ToolName, SpaceKey: req.SpaceKey, ContentID: req.TargetID,
		ApprovalID: &reqID, Success: true, Decision: map[bool]string{true: "approve", false: "reject"}[approve],
